tile_vm_memory.query:
timeseries {
  used  = avg(`custom.proxmox.vm.memory.used`),
  total = avg(`custom.proxmox.vm.memory.total`)
}, by: {vm_name, node_name, cluster_name}
| filter cluster_name == $cluster_name
| filter node_name == $node_name
| filter vm_name == $vm_name

tile_vm_balloon.query:
timeseries {
  current = avg(`custom.proxmox.vm.balloon.current`),
  target  = avg(`custom.proxmox.vm.balloon.target`)
}, by: {vm_name, node_name, cluster_name}
| filter cluster_name == $cluster_name
| filter node_name == $node_name
| filter vm_name == $vm_name

